// Block (composition) — a Drawer-based navigation for compact viewports.
// Contract: docs/rules/block-contract.md. Drawer owns all open/close behavior;
// this Block only arranges Button, Link, and Stack. Mints no tokens.
import { Button } from "../components/Button";
import { DrawerContent, DrawerHeader, DrawerTitle, DrawerTrigger } from "../components/Drawer";
import { Link } from "../components/Link";
import { Stack } from "../layouts/Stack";
import "./MobileNav.css";

export interface MobileNavProps {
  /** Navigation destinations shown in the drawer. */
  links: { label: string; href: string }[];
  /** Trigger text. */
  label?: string;
  /** Drawer heading. */
  title?: string;
}

export function MobileNav({ links, label = "Menu", title = "Navigation" }: MobileNavProps) {
  return (
    <DrawerTrigger>
      <Button variant="secondary" size="small" className="sd-mobilenav">
        {label}
      </Button>
      <DrawerContent side="start" className="sd-mobilenav__drawer"
        header={
          <DrawerHeader>
            <DrawerTitle>{title}</DrawerTitle>
          </DrawerHeader>
        }
      >
        <>
          <Stack as="nav" gap="small" aria-label={title} className="sd-mobilenav__links">
            {links.map((link, index) => (
              <Link key={`${link.label}-${index}`} href={link.href} variant="quiet" className="sd-mobilenav__link sd-type-label-medium">
                {link.label}
              </Link>
            ))}
          </Stack>
        </>
      </DrawerContent>
    </DrawerTrigger>
  );
}

/* MobileNav.css — .sd-mobilenav (Block)
   Arrangement only: the trigger stays compact while the Drawer navigation fills
   its available panel width. Drawer owns the overlay, panel, and interactions. */
.sd-mobilenav {
  flex-shrink: 0;
}

.sd-mobilenav__links,
.sd-mobilenav__link {
  width: 100%;
}
